export function budgetStatus(
  budgetedCents: Cents,
  rolloverCents: Cents,
  spentCents: Cents,
  warningRatio = DEFAULT_WARNING_RATIO,
): BudgetStatus {
  const available = budgetedCents + rolloverCents;
  if (budgetedCents === 0 && rolloverCents === 0) return spentCents > 0 ? 'unbudgeted' : 'none';
  if (spentCents > available) return 'over';
  if (available > 0 && spentCents >= available * warningRatio) return 'warning';
  return 'ok';
}

const key = (month: string, categoryId: string) => `${month}|${categoryId}`;

/** Expense spending per (month, category). Positive = money spent. */
export function spendingIndex(totals: readonly CategoryMonthTotal[]): Map<string, Cents> {
  const map = new Map<string, Cents>();
  for (const t of totals) {
    if (t.kind !== 'expense' || !t.categoryId) continue;
    const k = key(monthStart(t.month), t.categoryId);
    map.set(k, (map.get(k) ?? 0) - t.totalCents);
  }
  return map;
}

export function budgetIndex(budgets: readonly Budget[]): Map<string, Cents> {
  const map = new Map<string, Cents>();
  for (const b of budgets) map.set(key(monthStart(b.month), b.categoryId), b.amountCents);
  return map;
}

/** The month rollover accrual starts for a category, or null if rollover is off. */
export function rolloverStart(category: Category, budgets: readonly Budget[]): MonthStart | null {
  if (!category.rolloverEnabled) return null;
  if (category.rolloverStartMonth) return monthStart(category.rolloverStartMonth);
  let earliest: MonthStart | null = null;
  for (const b of budgets) {
    if (b.categoryId !== category.id) continue;
    const m = monthStart(b.month);
    if (!earliest || m < earliest) earliest = m;
  }
  return earliest;
}

/**
 * Amount carried into `month` for a rollover category. Positive = unused
 * budget available; negative = overspending to make up.
 */
export function rolloverCarryIn(
  category: Category,
  month: MonthStart,
  budgets: ReadonlyMap<string, Cents>,
  spending: ReadonlyMap<string, Cents>,
  start: MonthStart | null,
): Cents {
  if (!category.rolloverEnabled || !start || start >= month) return 0;
  let carry = 0;
  for (let m = start; m < month; m = addMonthsToMonth(m, 1)) {
    const budgeted = budgets.get(key(m, category.id)) ?? 0;
    const spent = spending.get(key(m, category.id)) ?? 0;
    carry = budgeted + carry - spent;
  }
  return carry;
}

/**
 * Earliest month of history `computeBudgetMonth` needs for `month`
 * (so the data layer can fetch just enough totals and budgets).
 */
export function budgetHistoryStart(
  categories: readonly Category[],
  month: MonthStart,
  knownBudgets: readonly Budget[] = [],
): MonthStart {
  let earliest = monthStart(month);
  for (const c of categories) {
    if (!c.rolloverEnabled) continue;
    const start = rolloverStart(c, knownBudgets);
    if (start && start < earliest) earliest = start;
  }
  return earliest;
}

function isBudgetable(c: Category): boolean {
  return c.kind === 'expense';
}

export function computeBudgetMonth(input: BudgetMonthInput): BudgetMonthView {
  const month = monthStart(input.month);
  const warningRatio = input.warningRatio ?? DEFAULT_WARNING_RATIO;
  const spending = spendingIndex(input.totals);
  const budgets = budgetIndex(input.budgets);

  const categories = input.categories.filter(isBudgetable);
  const known = new Set(input.categories.map((c) => c.id));
  const childrenOf = new Map<string, Category[]>();
  for (const c of categories) {
    if (!c.parentId) continue;
    const list = childrenOf.get(c.parentId) ?? [];
    list.push(c);
    childrenOf.set(c.parentId, list);
  }

  const leafRow = (c: Category): CategoryBudgetRow => {
    const budgetedCents = budgets.get(key(month, c.id)) ?? 0;
    const rolloverCents = rolloverCarryIn(c, month, budgets, spending, rolloverStart(c, input.budgets));
    const spentCents = spending.get(key(month, c.id)) ?? 0;
    const availableCents = budgetedCents + rolloverCents;
    return {
      categoryId: c.id,
      parentId: c.parentId,
      name: c.name,
      color: c.color,
      sortOrder: c.sortOrder,
      isGroup: false,
      isArchived: c.isArchived,
      rolloverEnabled: c.rolloverEnabled,
      budgetedCents,
      rolloverCents,
      availableCents,
      spentCents,
      remainingCents: availableCents - spentCents,
      percentUsed: availableCents > 0 ? spentCents / availableCents : null,
      status: budgetStatus(budgetedCents, rolloverCents, spentCents, warningRatio),
    };
  };

  // Archived categories stay visible only while they still matter this month.
  const visible = (r: CategoryBudgetRow) =>
    !r.isArchived || r.budgetedCents !== 0 || r.spentCents !== 0 || r.rolloverCents !== 0;

  const bySort = (a: { sortOrder: number; name: string }, b: { sortOrder: number; name: string }) =>
    a.sortOrder - b.sortOrder || a.name.localeCompare(b.name);

  const sections: BudgetSection[] = [];
  const allLeafRows: CategoryBudgetRow[] = [];

  for (const top of categories.filter((c) => !c.parentId).sort(bySort)) {
    const kids = (childrenOf.get(top.id) ?? []).sort(bySort);
    if (kids.length === 0) {
      const row = leafRow(top);
      if (!visible(row)) continue;
      allLeafRows.push(row);
      sections.push({ row, children: [] });
      continue;
    }

    const children = kids.map(leafRow).filter(visible);
    // Spending assigned directly to the group (not a child) still counts.
    const direct = leafRow(top);
    allLeafRows.push(...children, direct);

    const sum = (f: (r: CategoryBudgetRow) => Cents) => children.reduce((acc, r) => acc + f(r), 0) + f(direct);
    const budgetedCents = sum((r) => r.budgetedCents);
    const rolloverCents = sum((r) => r.rolloverCents);
    const spentCents = sum((r) => r.spentCents);
    const availableCents = budgetedCents + rolloverCents;
    const row: CategoryBudgetRow = {
      ...direct,
      isGroup: true,
      budgetedCents,
      rolloverCents,
      availableCents,
      spentCents,
      remainingCents: availableCents - spentCents,
      percentUsed: availableCents > 0 ? spentCents / availableCents : null,
      status: budgetStatus(budgetedCents, rolloverCents, spentCents, warningRatio),
    };
    if (!visible(row) && children.length === 0) continue;
    sections.push({ row, children });
  }

  // Spending that has no (known, expense) category.
  let uncategorizedSpentCents = 0;
  let incomeCents = 0;
  let totalSpentCents = 0;
  const expenseIds = new Set(categories.map((c) => c.id));
  for (const t of input.totals) {
    if (monthStart(t.month) !== month) continue;
    if (t.kind === 'income') incomeCents += t.totalCents;
    if (t.kind !== 'expense') continue;
    totalSpentCents -= t.totalCents;
    if (!t.categoryId || !known.has(t.categoryId) || !expenseIds.has(t.categoryId)) {
      uncategorizedSpentCents -= t.totalCents;
    }
  }

  const budgetedCents = allLeafRows.reduce((a, r) => a + r.budgetedCents, 0);
  const rolloverCents = allLeafRows.reduce((a, r) => a + r.rolloverCents, 0);
  const availableCents = budgetedCents + rolloverCents;
  const unbudgetedSpentCents =
    allLeafRows.filter((r) => r.status === 'unbudgeted').reduce((a, r) => a + r.spentCents, 0) +
    uncategorizedSpentCents;

  return {
    month,
    sections,
    summary: {
      month,
      budgetedCents,
      rolloverCents,
      availableCents,
      spentCents: totalSpentCents,
      remainingCents: availableCents - totalSpentCents,
      uncategorizedSpentCents,
      unbudgetedSpentCents,
      incomeCents,
      percentUsed: availableCents > 0 ? totalSpentCents / availableCents : null,
      status: budgetStatus(budgetedCents, rolloverCents, totalSpentCents, warningRatio),
      overBudgetCategoryCount: allLeafRows.filter((r) => r.status === 'over').length,
      warningCategoryCount: allLeafRows.filter((r) => r.status === 'warning').length,
    },
  };
}

/** Budgets to create when copying one month's budget into another (skips existing). */
export function planCopyBudgets(
  from: readonly Budget[],
  existingInTarget: readonly Budget[],
  targetMonth: MonthStart,
): Budget[] {
  const existing = new Set(existingInTarget.map((b) => b.categoryId));
  return from
    .filter((b) => b.amountCents > 0 && !existing.has(b.categoryId))
    .map((b) => ({ categoryId: b.categoryId, month: monthStart(targetMonth), amountCents: b.amountCents }));
}
